ing{/other_user}","gists_url":"https://api.github.com/users/johnlindquist/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/johnlindquist","id":36073,"login":"johnlindquist","node_id":"MDQ6VXNlcjM2MDcz","organizations_url":"https://api.github.com/users/johnlindquist/orgs","received_events_url":"https://api.github.com/users/johnlindquist/received_events","repos_url":"https://api.github.com/users/johnlindquist/repos","site_admin":false,"starred_url":"https://api.github.com/users/johnlindquist/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/johnlindquist/subscriptions","type":"User","url":"https://api.github.com/users/johnlindquist","user_view_type":"public"},"comments_url":"https://api.github.com/repos/SamSammane/vercel-plugin/commits/4978c36f69658b00f7233bdce11a80c167319d36/comments","commit":{"author":{"date":"2026-03-08T17:38:07Z","email":"johnlindquist@gmail.com","name":"John Lindquist"},"comment_count":0,"committer":{"date":"2026-03-08T17:38:07Z","email":"johnlindquist@gmail.com","name":"John Lindquist"},"message":"docs(geist): expand skill metadata and typography guidance\n\nBroaden the geist skill trigger metadata so layout, globals, styles, and install commands\nmap to the skill more reliably in monorepos and app-router projects.\nAdd explicit typography direction so the skill guides Vercel-style hierarchy,\nfamily usage, and common anti-patterns instead of acting like a bare font import.\n\nVerified: node --input-type=module <<''EOF''\nimport { readFile } from ''node:fs/promises'';\nimport { extractFrontmatter, parseSkillFrontmatter } from ''./hooks/skill-map-frontmatter.mjs'';\n\nconst content = await readFile(''skills/geist/SKILL.md'', ''utf8'');\nconst { yaml, body } = extractFrontmatter(content);\nconst parsed = parseSkillFrontmatter(yaml);\n\nconst expectedPaths = [\n  ''app/layout.*'',\n  ''src/app/layout.*'',\n  ''app/globals.css'',\n  ''src/app/globals.css'',\n  ''styles/**'',\n  ''tailwind.config.*'',\n  ''apps/*/app/layout.*'',\n  ''apps/*/src/app/layout.*'',\n  ''apps/*/app/globals.css'',\n  ''apps/*/src/app/globals.css'',\n];\nconst expectedImports = [''geist'', ''geist/font'', ''geist/font/*''];\n\nfunction assert(condition, message) {\n  if (!condition) throw new Error(message);\n}\n\nassert(parsed.description.includes(''typography system''), ''description should mention typography system'');\nassert(parsed.description.includes(''aesthetic guidance''), ''description should mention aesthetic guidance'');\nassert(parsed.metadata.priority === 4, ''priority should be 4'');\nassert(JSON.stringify(parsed.metadata.pathPatterns) === JSON.stringify(expectedPaths), ''pathPatterns should match requested list'');\nassert(JSON.stringify(parsed.metadata.importPatterns) === JSON.stringify(expectedImports), ''importPatterns should match requested list'');\nassert(Array.isArray(parsed.metadata.bashPatterns) && parsed.metadata.bashPatterns.length === 4, ''bashPatterns should include npm/pnpm/bun/yarn install patterns'');\n\nconst fontWeightsIndex = body.indexOf(''## Font Weights'');\nconst typographyIndex = body.indexOf(''## Typography Direction for Geist'');\nconst subsetIndex = body.indexOf(''## Subset Configuration'');\nassert(fontWeightsIndex !== -1, ''Font Weights heading should exist'');\nassert(typographyIndex > fontWeightsIndex, ''Typography Direction section should come after Font Weights'');\nassert(subsetIndex === -1 || typographyIndex < subsetIndex, ''Typography Direction section should come before Subset Configuration'');\nassert(body.includes(''### What good looks like''), ''Typography section should include What good looks like'');\nassert(body.includes(''### Default type recipes''), ''Typography section should include default type recipes'');\nassert(body.includes(''### Where to use each family''), ''Typography section should include family guidance'');\nassert(body.includes(''### Anti-patterns''), ''Typography section should include anti-patterns'');\nassert(body.includes(''text-lg tracking-tight''), ''Typography recipes should include text-lg section heading'');\nassert(body.includes(''text-xl tracking-tight''), ''Typography recipes should include text-xl section heading'');\n\nconsole.log(''frontmatter and section structure verified'');\nEOF\nVerified: node --input-type=module <<''EOF''\nimport { readFile } from ''node:fs/promises'';\nimport { extractFrontmatter, parseSkillFrontmatter } from ''./hooks/skill-map-frontmatter.mjs'';\nimport { compileSkillPatterns, matchBashWithReason, matchImportWithReason, matchPathWithReason } from ''./hooks/patterns.mjs'';\n\nconst content = await readFile(''skills/geist/SKILL.md'', ''utf8'');\nconst { yaml } = extractFrontmatter(content);\nconst parsed = parseSkillFrontmatter(yaml);\nconst [compiled] = compileSkillPatterns({ geist: parsed.metadata });\n\nfunction assert(condition, message) {\n  if (!condition) throw new Error(message);\n}\n\nfor (const filePath of [\n  ''app/layout.tsx'',\n  ''src/app/layout.tsx'',\n  ''app/globals.css'',\n  ''apps/web/app/layout.tsx'',\n  ''apps/web/src/app/globals.css'',\n  ''styles/tokens.css'',\n  ''tailwind.config.ts'',\n]) {\n  assert(matchPathWithReason(filePath, compiled.compiledPaths), );\n}\n\nfor (const command of [\n  ''npm install geist'',\n  ''pnpm add geist'',\n  ''bun install geist'',\n  ''yarn add geist'',\n]) {\n  assert(matchBashWithReason(command, compiled.compiledBash), );\n}\n\nfor (const source of [\n  \"import { GeistSans } from ''geist/font/sans''\",\n  \"const mono = require(''geist/font/mono'')\",\n  \"await import(''geist'')\",\n]) {\n  assert(matchImportWithReason(source, compiled.compiledImports), );\n}\n\nconsole.log(''path, bash, and import pattern matching verified'');\nEOF\nSwarm-Agent: codex-geist","tree":{"sha":"3e895e3166c0f181fe00959c7f55b8378c47d87e","url":"https://api.github.com/repos/SamSammane/vercel-plugin/git/trees/3e895e3166c0f181fe00959c7f55b8378c47d87e"},"url":"https://api.github.com/repos/SamSammane/vercel-plug