s","tree":{"sha":"c8bfbee979d687a5279b02c7950ad60b9c0145c9","url":"https://api.github.com/repos/SamSammane/vercel-plugin/git/trees/c8bfbee979d687a5279b02c7950ad60b9c0145c9"},"url":"https://api.github.com/repos/SamSammane/vercel-plugin/git/commits/847f368f6bb76ba64a99fdd15eeebb067780b94a","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/36073?v=4","events_url":"https://api.github.com/users/johnlindquist/events{/privacy}","followers_url":"https://api.github.com/users/johnlindquist/followers","following_url":"https://api.github.com/users/johnlindquist/following{/other_user}","gists_url":"https://api.github.com/users/johnlindquist/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/johnlindquist","id":36073,"login":"johnlindquist","node_id":"MDQ6VXNlcjM2MDcz","organizations_url":"https://api.github.com/users/johnlindquist/orgs","received_events_url":"https://api.github.com/users/johnlindquist/received_events","repos_url":"https://api.github.com/users/johnlindquist/repos","site_admin":false,"starred_url":"https://api.github.com/users/johnlindquist/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/johnlindquist/subscriptions","type":"User","url":"https://api.github.com/users/johnlindquist","user_view_type":"public"},"html_url":"https://github.com/SamSammane/vercel-plugin/commit/847f368f6bb76ba64a99fdd15eeebb067780b94a","node_id":"C_kwDORh6aR9oAKDg0N2YzNjhmNmJiNzZiYTY0YTk5ZmRkMTVlZWViYjA2Nzc4MGI5NGE","parents":[{"html_url":"https://github.com/SamSammane/vercel-plugin/commit/23e6a5646155b719136492f9cf2f2177f636d885","sha":"23e6a5646155b719136492f9cf2f2177f636d885","url":"https://api.github.com/repos/SamSammane/vercel-plugin/commits/23e6a5646155b719136492f9cf2f2177f636d885"}],"sha":"847f368f6bb76ba64a99fdd15eeebb067780b94a","url":"https://api.github.com/repos/SamSammane/vercel-plugin/commits/847f368f6bb76ba64a99fdd15