":"https://api.github.com/repos/SamSammane/vercel-plugin/git/trees/db848fbca024e638475c6ce9e5ff8621f5f46796"},"url":"https://api.github.com/repos/SamSammane/vercel-plugin/git/commits/23e6a5646155b719136492f9cf2f2177f636d885","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/36073?v=4","events_url":"https://api.github.com/users/johnlindquist/events{/privacy}","followers_url":"https://api.github.com/users/johnlindquist/followers","following_url":"https://api.github.com/users/johnlindquist/following{/other_user}","gists_url":"https://api.github.com/users/johnlindquist/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/johnlindquist","id":36073,"login":"johnlindquist","node_id":"MDQ6VXNlcjM2MDcz","organizations_url":"https://api.github.com/users/johnlindquist/orgs","received_events_url":"https://api.github.com/users/johnlindquist/received_events","repos_url":"https://api.github.com/users/johnlindquist/repos","site_admin":false,"starred_url":"https://api.github.com/users/johnlindquist/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/johnlindquist/subscriptions","type":"User","url":"https://api.github.com/users/johnlindquist","user_view_type":"public"},"html_url":"https://github.com/SamSammane/vercel-plugin/commit/23e6a5646155b719136492f9cf2f2177f636d885","node_id":"C_kwDORh6aR9oAKDIzZTZhNTY0NjE1NWI3MTkxMzY0OTJmOWNmMmYyMTc3ZjYzNmQ4ODU","parents":[{"html_url":"https://github.com/SamSammane/vercel-plugin/commit/73d03a96ab0ff0b255cb9bd3a85f5b49a103b737","sha":"73d03a96ab0ff0b255cb9bd3a85f5b49a103b737","url":"https://api.github.com/repos/SamSammane/vercel-plugin/commits/73d03a96ab0ff0b255cb9bd3a85f5b49a103b737"}],"sha":"23e6a5646155b719136492f9cf2f2177f636d885","url":"https://api.github.com/repos/SamSammane/vercel-plugin/commits/23e6a5646155b719136492f9cf2f2177f636d885"},{"author":{"avatar_url":"https://avatars.githu